static dm_DsTproverkau2ePeremennaya *dm_DsTproverkau2ePeremennaya_share(dm_DsTproverkau2ePeremennaya *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsTproverkau2ePeremennaya_release(dm_DsTproverkau2ePeremennaya *d) { if (d) dan_hdr_release(&d->h, dm_DsTproverkau2ePeremennaya_destroy); }
