static bool dm_DsLTrazboru2eUzel_eq(const dm_DsLTrazboru2eUzel *x, const dm_DsLTrazboru2eUzel *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsLTrazboru2eUzel_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dl_LTrazboru2eUzel* a = x->vals[e]; dl_LTrazboru2eUzel* b = y->vals[f];
        if (!(dl_LTrazboru2eUzel_eq(a, b))) return false;
    }
    return true;
}


/* ---- dictionary {цел: стр} ---- */
struct dm_Dis { dan_hdr h; int64_t len, n, cap, slots; int64_t *keys; dan_str *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_Dis_destroy(dan_hdr *h) {
    dm_Dis *d = (dm_Dis *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { DAN_NOREL(d->keys[e]); dan_str_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_Dis *dm_Dis_new(void) {
    dm_Dis *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_Dis_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_Dis *dm_Dis_new_detached(void) {
    dm_Dis *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_Dis *dm_Dis_share(dm_Dis *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_Dis_release(dm_Dis *d) { if (d) dan_hdr_release(&d->h, dm_Dis_destroy); }
static void dm_Dis_give(dm_Dis *d) { if (d) dan_hdr_give(&d->h, dm_Dis_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_Dis_block(dm_Dis *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(int64_t) * c + 7) & ~(size_t)7, vb = (sizeof(dan_str) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (int64_t *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_Dis_reindex(dm_Dis *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_Dis_lookup(const dm_Dis *d, int64_t k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { int64_t a = d->keys[e], b = k; if ((a == b)) return e; }
    }
}
static void dm_Dis_grow(dm_Dis *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    int64_t *keys = d->keys; dan_str *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_Dis_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_Dis_reindex(d);
}
static void dm_Dis_put(dm_Dis *d, int64_t k, dan_str v) {
    uint64_t h = dan_hash_i(k);
    int64_t e = dm_Dis_lookup(d, k, h);
    if (e >= 0) { dan_str old = d->vals[e]; d->vals[e] = dan_str_share(v); dan_str_release(old); (void)old; return; }
    if (d->n == d->cap) dm_Dis_grow(d);
    e = d->n++;
    d->keys[e] = DAN_ID(k); d->vals[e] = dan_str_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_Dis_put_raw(dm_Dis *d, int64_t k, dan_str v) {
    uint64_t h = dan_hash_i(k);
    if (d->n == d->cap) dm_Dis_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dan_str *dm_Dis_slot(dm_Dis *d, int64_t k, dan_str v) {
    uint64_t h = dan_hash_i(k);
    int64_t e = dm_Dis_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_Dis_grow(d);
        e = d->n++;
        d->keys[e] = DAN_ID(k); d->vals[e] = dan_str_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_Dis *dm_Dis_from(int64_t n, const int64_t *ks, const dan_str *vs) {
    dm_Dis *d = dm_Dis_new();
    for (int64_t i = 0; i < n; i++) dm_Dis_put(d, ks[i], vs[i]);
    return d;
}
static dan_str dm_Dis_get(const dm_Dis *d, int64_t k, int line) {
    int64_t e = dm_Dis_lookup(d, k, dan_hash_i(k));
    if (e < 0) dan_key_error(dan_int_to_str(k), line);
    return d->vals[e];
}
static dan_str *dm_Dis_at(dm_Dis *d, int64_t k, int line) {
    int64_t e = dm_Dis_lookup(d, k, dan_hash_i(k));
    if (e < 0) dan_key_error(dan_int_to_str(k), line);
    return &d->vals[e];
}
static bool dm_Dis_contains(const dm_Dis *d, int64_t k) { return dm_Dis_lookup(d, k, dan_hash_i(k)) >= 0; }

static do_s dm_Dis_find(const dm_Dis *d, int64_t k) {
    int64_t e = dm_Dis_lookup(d, k, dan_hash_i(k));
    return e < 0 ? do_s_none() : do_s_some(d->vals[e]);
}
static dan_str dm_Dis_get_or(const dm_Dis *d, int64_t k, dan_str v) {
    int64_t e = dm_Dis_lookup(d, k, dan_hash_i(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_Dis_remove(dm_Dis *d, int64_t k) {
    int64_t e = dm_Dis_lookup(d, k, dan_hash_i(k));
    if (e >= 0) { d->alive[e] = false; d->len--; DAN_NOREL(d->keys[e]); dan_str_release(d->vals[e]); }
}
static dl_Li *dm_Dis_keys(const dm_Dis *d) {
    dl_Li *r = dl_Li_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Li_push(r, d->keys[e]);
    return r;
}
static dl_Ls *dm_Dis_values(const dm_Dis *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dis *dm_Dis_copy(const dm_Dis *d) {
    dm_Dis *r = dm_Dis_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dis_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = DAN_ID(d->keys[e]); r->vals[m] = dan_str_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dis_reindex(r);
    return r;
}
static dm_Dis *dm_Dis_mut(dm_Dis **pp) {
    dm_Dis *d = *pp;
    if (d->h.rc > 1) { dm_Dis *r = dm_Dis_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dis_str(const dm_Dis *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_int_to_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_quote_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dis_write(const dm_Dis *d) { fputs(dm_Dis_str(d), stdout); }


static bool dm_Dis_eq(const dm_Dis *x, const dm_Dis *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dis_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dan_str a = x->vals[e]; dan_str b = y->vals[f];
        if (!(dan_str_eq(a, b))) return false;
    }
    return true;
}

